trait Import {
    fn parse(&self, source: &str) -> Vec<Row>;      // required step
    fn store(&self, rows: &[Row]) -> Report;        // required step
    fn before_store(&self, _rows: &[Row]) {}        // hook: default body

    fn run(&self, source: &str) -> Report {         // skeleton (provided method)
        let rows = self.parse(source);
        self.before_store(&rows);
        self.store(&rows)
    }
}
